                Set<Long> curSums = new HashSet<>(); // 当前盒子删除一张卡片后的剩余总分
                for (int a : arr) {
                    curSums.add(total - a);
                }
                // 检查是否与之前盒子的剩余总分匹配
                for (long s : curSums) {
                    if (seen.containsKey(s) && seen.get(s) != boxIdx) {
                        found = true;
                    }
                }
                // 记录当前盒子的剩余总分
                for (long s : curSums) {
                    seen.put(s, boxIdx);
                }
            }
            sb.append(found ? "YES" : "NO").append("\n");
        }
        System.out.print(sb);
        sc.close();
    }
}
